<?php
if(!defined('ABSPATH'))exit;
function dgs_school_roster_query($year,$filters=array(),$limit=20,$offset=0,$count=false){
 if(!current_user_can('dgs_manage_education'))return $count?0:array();global $wpdb;$e=dgs_edu_tables();$args=array($year,$wpdb->get_blog_prefix().'capabilities','%"dgs_student"%');$where='';if(!empty($filters['grade'])){$where.=' AND c.grade=%d';$args[]=absint($filters['grade']);}if(!empty($filters['field'])){$where.=' AND c.field=%s';$args[]=sanitize_key($filters['field']);}if(!empty($filters['class'])){$where.=' AND c.id=%d';$args[]=absint($filters['class']);}
 $sql=" FROM {$wpdb->users} u JOIN {$wpdb->usermeta} caps ON caps.user_id=u.ID LEFT JOIN {$e['enrollments']} en ON en.student_id=u.ID AND en.school_year=%s LEFT JOIN {$e['classes']} c ON c.id=en.class_id WHERE caps.meta_key=%s AND caps.meta_value LIKE %s $where";
 if($count)return (int)$wpdb->get_var($wpdb->prepare('SELECT COUNT(DISTINCT u.ID)'.$sql,$args));$args[]=max(1,min(2001,$limit));$args[]=max(0,$offset);return $wpdb->get_results($wpdb->prepare('SELECT DISTINCT u.ID,u.user_login,u.display_name,en.id AS enrollment_id,c.id AS class_id,c.title AS class_title,c.grade,c.field'.$sql.' ORDER BY u.display_name,u.ID LIMIT %d OFFSET %d',$args));
}
function dgs_school_student_create($d){

 if(!current_user_can('dgs_manage_education'))return dgs_edu_error('access','اجازه مدیریت ندارید.');foreach($d as $v)if(!is_scalar($v))return dgs_edu_error('input','اطلاعات معتبر نیست.');if(username_exists(dgs_edu_digits((string)($d['national_id']??''))))return dgs_edu_error('exists','این حساب وجود دارد؛ از انتساب کلاس یا اکسل برای سال جدید استفاده کنید.');$row=array();foreach(dgs_school_columns() as $k)$row[]=$d[$k==='full_name'?'name':$k]??'';return dgs_school_import_rows(array($row),$d['year']??'');
}
function dgs_school_section(){if(isset($_GET['school_section'])&&is_string($_GET['school_section']))$raw=sanitize_key($_GET['school_section']);else{$raw=dgs_att_get('dg_tab');$raw=array('classes'=>'classes','subjects'=>'subjects','assignments'=>'teaching')[$raw]??'students';}return in_array($raw,array('students','classes','subjects','teaching'),true)?$raw:'students';}
function dgs_edu_view_education($year){
 if(!current_user_can('dgs_manage_education'))return '';$tab=dgs_school_section();if(dgs_att_get('sd_add')==='1')return dgs_admission_page($year);$out='<div class="dsp-school dsp-education">'.dgs_school_title('مدیریت آموزشی','مدیریت دانش‌آموزان، کلاس‌ها، دروس و تخصیص دبیر').'<nav class="dsp-education-tabs">';foreach(array('students'=>'دانش‌آموزان','classes'=>'کلاس‌ها','subjects'=>'دروس','teaching'=>'دبیران و تخصیص درس') as $key=>$title)$out.='<a '.($key===$tab?'aria-current="page"':'').' href="'.esc_url(dgs_school_url('education',$year,array('school_section'=>$key))).'">'.esc_html($title).'</a>';$out.='</nav>';
 if($tab==='classes')return $out.dgs_edu_view_classes($year).'</div>';if($tab==='subjects')return $out.dgs_edu_view_subjects($year).'</div>';if($tab==='teaching'){if(dgs_att_get('dt_add')==='1'||absint(dgs_att_get('dt_edit')))return $out.dgs_teacher_manager($year).'</div>';return $out.dgs_teacher_manager($year).dgs_edu_view_assignments($year).'</div>';}
 $grade=absint(dgs_att_get('sd_grade'));$field=sanitize_key(dgs_att_get('sd_field'));$class=absint(dgs_att_get('sd_class'));$filters=array('grade'=>$grade,'field'=>$field,'class'=>$class);$classes=dgs_edu_classes($year);$options=dgs_edu_class_options($classes);$total=dgs_school_roster_query($year,$filters,20,0,true);$page=max(1,min(max(1,(int)ceil($total/20)),absint(dgs_att_get('sd_page','1'))));$rows=dgs_school_roster_query($year,$filters,20,($page-1)*20);$roster_options=dgs_edu_user_options('dgs_student');
 $out.=dgs_school_year_box($year).'<section class="dsp-card"><form method="get" class="dge-filter" action="'.esc_url(dgs_page_url('portal')).'"><input type="hidden" name="dg_tab" value="education"><input type="hidden" name="dg_year" value="'.esc_attr($year).'">'.dgs_edu_select('sd_grade','پایه',array(10=>'دهم',11=>'یازدهم',12=>'دوازدهم'),$grade,false).dgs_edu_select('sd_field','رشته',dgs_edu_fields(),$field,false).dgs_edu_select('sd_class','کلاس',$options,$class,false).'<button class="dg-btn">⌕ جست‌وجو</button></form></section><section class="dsp-card"><div class="dsp-section-head"><div><h3>'.dgs_school_icon('users').' فهرست دانش‌آموزان</h3><small>تعداد: '.esc_html(dgs_fa_digits($total)).' نفر</small></div><div class="dsp-actions"><a class="dg-btn" href="'.esc_url(dgs_school_url('education',$year,array('sd_add'=>1))).'">'.dgs_school_icon('users').' افزودن دانش‌آموز</a><button class="dg-btn dg-btn-outline" type="button" data-school-dialog="dsp-import">ورود از اکسل ▣</button><a class="dg-btn dg-btn-outline" href="'.esc_url(wp_nonce_url(add_query_arg(array('action'=>'dgs_school_export','year'=>$year,'sd_grade'=>$grade,'sd_field'=>$field,'sd_class'=>$class),admin_url('admin-post.php')),'dgs_school_export')).'">خروجی اکسل ↓</a></div></div>'.dgs_edu_table_start(array('ردیف','کد دانش‌آموز','نام و نام خانوادگی','پایه','رشته','کلاس','شماره تماس ولی','عملیات'));
 foreach($rows as $i=>$r){$phone=get_user_meta($r->ID,'_dgs_contact_phone',true);$guardian=get_user_meta($r->ID,'_dgs_guardian_phone',true);$code=get_user_meta($r->ID,'_dgs_student_code',true)?:$r->ID;$out.='<tr><td>'.esc_html(dgs_fa_digits(($page-1)*20+$i+1)).'</td><td>'.esc_html(dgs_fa_digits($code)).'</td><td>'.esc_html($r->display_name).'</td><td>'.esc_html(dgs_edu_grade_label($r->grade)).'</td><td>'.esc_html(dgs_edu_fields()[$r->field]??'—').'</td><td>'.esc_html($r->class_id?dgs_edu_class_label($r):'تعیین نشده').'</td><td dir="ltr">'.esc_html($guardian?dgs_fa_digits($guardian):'—').'</td><td><div class="dsp-row-actions"><a class="dsp-operation dsp-op-record" title="پرونده دانش‌آموز" aria-label="پرونده دانش‌آموز" href="'.esc_url(dgs_school_url('records',$year,array('student_id'=>$r->ID))).'">'.dgs_school_icon('book').'<span>پرونده</span></a><button class="dsp-operation" type="button" title="ویرایش" aria-label="ویرایش '.esc_attr($r->display_name).'" data-school-edit="'.(int)$r->ID.'" data-name="'.esc_attr($r->display_name).'" data-phone="'.esc_attr($phone).'" data-guardian="'.esc_attr($guardian).'" data-code="'.esc_attr(get_user_meta($r->ID,'_dgs_student_code',true)).'">'.dgs_school_icon('edit').'<span>ویرایش</span></button>';
 if($r->enrollment_id)$out.=dgs_edu_form_start('unenroll','education',$year).'<input type="hidden" name="enrollment_id" value="'.(int)$r->enrollment_id.'"><button title="برداشتن از کلاس" aria-label="برداشتن انتساب کلاس" class="dsp-trash dsp-operation" data-dge-confirm="انتساب کلاس این سال برداشته شود؟ حساب و سوابق دانش‌آموز حذف نمی‌شود.">'.dgs_school_icon('users').'<span>برداشتن از کلاس</span></button></form>';
 $out.='<button class="dsp-operation" type="button" title="انتساب کلاس" aria-label="انتخاب برای انتساب" data-school-assign="'.(int)$r->ID.'">'.dgs_school_icon('class').'<span>انتساب کلاس</span></button></div></td></tr>';}
 $out.='</tbody></table></div><nav class="dge-pagination">';foreach(array(-1=>'قبلی',1=>'بعدی') as $step=>$label)if($page+$step>0&&$page+$step<=ceil($total/20))$out.='<a href="'.esc_url(dgs_school_url('education',$year,array('sd_grade'=>$grade,'sd_field'=>$field,'sd_class'=>$class,'sd_page'=>$page+$step))).'">'.$label.'</a>';$out.='<span>'.esc_html(dgs_fa_digits($page)).'</span></nav></section><div class="dsp-grid-two"><section class="dsp-card" id="dsp-assign-student"><h3>'.dgs_school_icon('users').' انتساب دانش‌آموز به کلاس</h3>'.dgs_school_form('assign',$year).dgs_edu_select('student_id','دانش‌آموز',$roster_options).dgs_edu_select('class_id','کلاس مقصد',$options).'<label class="dsp-checkbox"><input type="checkbox" name="replace" value="1">انتقال از کلاس قبلی با حفظ سوابق را تأیید می‌کنم.</label><button class="dg-btn dsp-wide">✓ ثبت انتساب به کلاس</button></form></section><section class="dsp-card"><h3>'.dgs_school_icon('class').' تخصیص دبیر به کلاس و درس</h3>'.dgs_edu_form_start('teach','assignments',$year).dgs_edu_select('class_id','کلاس',$options);
 $subjects=array();foreach(dgs_edu_subjects() as $s)$subjects[$s->id]=$s->title;$out.=dgs_edu_select('subject_id','درس',$subjects).dgs_edu_select('teacher_id','دبیر',dgs_edu_user_options('dgs_teacher')).'<label class="dsp-checkbox"><input type="checkbox" name="replace" value="1">جایگزینی دبیر قبلی در صورت وجود</label><button class="dg-btn dsp-wide">✓ ثبت تخصیص دبیر</button></form></section></div>';
 $out.='<dialog class="dsp-dialog" id="dsp-edit-student"><button type="button" class="dsp-dialog-close" data-school-close>×</button><h3>ویرایش مشخصات دانش‌آموز</h3>'.dgs_school_form('profile',$year).'<input name="student_id" type="hidden"><label>نام و نام خانوادگی<input name="name" maxlength="100" required></label><label>شماره تماس دانش‌آموز<input name="phone" dir="ltr" required></label><label>شماره تماس ولی<input name="guardian_phone" dir="ltr"></label><label>کد دانش‌آموز<input name="student_code" maxlength="30"></label><p class="dsp-footnote">نام کاربری کد ملی ثابت است و رمز تغییر نمی‌کند.</p><button class="dg-btn">ذخیره مشخصات</button></form></dialog>';
 $template=wp_nonce_url(add_query_arg(array('action'=>'dgs_school_export','year'=>$year,'template'=>1),admin_url('admin-post.php')),'dgs_school_export');$out.='<dialog class="dsp-dialog" id="dsp-import"><button type="button" class="dsp-dialog-close" data-school-close>×</button><h3>ورود از اکسل</h3><p class="dsp-footnote">الگوی کامل XLSX شامل اطلاعات هویتی، تماس، ولی و پذیرش؛ حداکثر ۱۰۰ دانش‌آموز در هر بار. ستون‌های تکمیلی اختیاری‌اند. ستون‌های کد ملی و شماره‌ها را متنی نگه دارید تا صفر اول حذف نشود. حساب موجود بازنویسی نمی‌شود. class_id شناسه کلاس فعال همان سال است.</p>'.dgs_admission_excel_help($classes).'<a class="dg-btn dg-btn-outline" href="'.esc_url($template).'">دریافت الگوی اکسل</a>'.dgs_school_form('import',$year).'<label>فایل الگو تکمیل‌شده<input type="file" name="roster_file" accept=".xlsx" required></label><button class="dg-btn">بررسی و ورود فایل</button></form></dialog>';
 return $out.'</div>';
}
